///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_submit
 * @description submit 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_submit = async function (action) {
    const sbmOptions = {
        id: "tx_fn_submit",
        method: "post",
        action: action ?? "/submission/submit.do?method=registerSubmitInformation",
        ref: "dma_submitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_SignCallback
 * @description Sign Callback 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_SignCallback = async function () {
    const sbmOptions = {
        id: "tx_SignCallback",
        method: "post",
        action: "/submission/submitCertificate.do",
        ref: "dma_SignCallbackReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/submission/submitCertificate.do",
        ref: "dma_loadListReq",
        target: "dlt_isuVo=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name SignCallback
 * @description Sign Callback 처리
 * @param {*} result result
 * @param {*} postData postData
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.SignCallback = async function (result, postData) {
    $c.util.getComponent('step5').src = '/img/submission/step/step_submission_1_5.gif';
    $c.util.getComponent('step6').src = '/img/submission/step/step_submission_1_6_selected.gif';
    (document.certiFrm || { elements: [] }).target = 'certiFrame';
    $c.util.getComponent('dma_submitReq').set('PKCS7SignedData', result);
    if (result) {
        await scwin.tx_SignCallback();
    } else {
        if (INI_ALERT) {
            INI_ALERT("전자서명에 실패하였습니다.");
        } else {
            await $c.win.alert("전자서명에 실패하였습니다.");
        }
    }
};

///////// 5. 일반/업무 함수 영역 /////////
