 * @param {*} comAbbrv comAbbrv
 * @param {*} isurSymbl isurSymbl
 * @param {*} fssUnqNo fssUnqNo
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo = function (isurCd, kisComCd, repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo) {
    (document.corpForm || { elements: [] }).txtisurCd.value = isurCd;
    (document.corpForm || { elements: [] }).txtfssUnqNo.value = fssUnqNo;
    (document.corpForm || { elements: [] }).txtcomNm.value = comNm;
    (document.corpForm || { elements: [] }).tgtIsuSrtCd.value = repIsuSrtCd;
    (document.corpForm || { elements: [] }).chkPop.value = 'Y';
};

/**
 * @method
 * @name isuSubmit
 * @description isu Submit 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.isuSubmit = async function () {
    (document.isuForm || { elements: [] }).action = "/submission/submit.do?method=searchIsuInfo";
    $c.util.getComponent('dma_submitReq').set('isuNm', $c.util.getComponent('ipt_searchIsuNm').getValue());
    const returnVal = await scwin.tx_fn_isuSubmit_xhr();
    $c.util.getComponent('isuList').render.innerHTML = returnVal;
};

/**
 * @method
 * @name submit
 * @description submit 처리
 * @param {*} ahthSvrType ahthSvrType
 * @param {*} ahthDdtm ahthDdtm
 * @param {*} ahthKeyNo ahthKeyNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.submit = async function (ahthSvrType, ahthDdtm, ahthKeyNo) {
    const tObj = $c.util.getComponent('slc_tgtIsuCdList').options;
    const submitTgtIsu = [];
    if (tObj.length === 0) {
        await $c.win.alert('대상 종목을  1종목 까지 선택하셔야 합니다.');
        return;
    } else {
        if (tObj.length > 1) {
            await $c.win.alert('대상 종목을  1종목만  선택하셔야 합니다.');
            return;
        } else {
            submitTgtIsu[0] = tObj[0].value;
            $c.util.getComponent("dma_submitReq").set("submitTgtIsu", submitTgtIsu);
        }
    }
    if (($c.util.getComponent('ipt_submitprnNm').getValue() == null ? '' : String($c.util.getComponent('ipt_submitprnNm').getValue())) === '') {
        await $c.win.alert('제출인 성명을 입력하셔야 합니다.');
        $c.util.getComponent("ipt_submitprnNm").focus();
        return;
    }
    if (($c.util.getComponent('ipt_telNo').getValue() == null ? '' : String($c.util.getComponent('ipt_telNo').getValue())) === '') {
        await $c.win.alert('전화번호를 입력하셔야 합니다.');
        $c.util.getComponent("ipt_telNo").focus();
        return;
    }
    if (($c.util.getComponent('ipt_submitprnEmail').getValue() == null ? '' : String($c.util.getComponent('ipt_submitprnEmail').getValue())) === '') {
        await $c.win.alert('이메일 정보를 입력하셔야 합니다.');
        $c.util.getComponent("ipt_submitprnEmail").focus();
        return;
    }
    $c.util.getComponent('dma_submitReq').set('ahthSvrIp', ahthSvrType);
    $c.util.getComponent('dma_submitReq').set('ahthDdtm', ahthDdtm);
    $c.util.getComponent('dma_submitReq').set('ahthKeyNo', ahthKeyNo);
    await scwin.tx_fn_submit('/submission/submit.do?method=registerSubmitInformation');
};

