/**
 * @method
 * @name certification
 * @description certification 처리
 * @param {*} vidType vidType
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.certification = async function (vidType) {
    const tObj = $c.util.getComponent('slc_tgtIsuCdList').options;
    const submitTgtIsu = [];
    if (tObj.length === 0) {
        await $c.win.alert('대상 종목을  1종목 까지 선택하셔야 합니다.');
        return;
    } else {
        if (tObj.length > 1) {
            await $c.win.alert('대상 종목을  1종목만  선택하셔야 합니다.');
            return;
        }
    }
    document.certiFrm.vid.value = vidType;
    let DNList = "";
    if (vidType) {
        DNList = realIssuerDN;
    } else {
        DNList = testIssuerDN;
    }
    INIWEBEX.login({ loginType: "sign", data: "login", processCallback: "SignCallback", isHtml5: false, viewType: "NONE", iniCache: true, vid: true, langType: "KOR", filterCertByOIDAlias: { enable: false, list: "" }, filterCertByIssuer: { enable: true, list: DNList } });
};

